/**
 * Dataset browser (SIH26078, Phase 6).
 *
 * Lists the datasets that have been ingested, with a badge for each that says
 * what kind of data it actually is.
 *
 * The three badges are the point of this component:
 *
 *  - **SYNTHETIC**        - generated by this project. No real observation.
 *  - **HISTORICAL**       - a real past period, e.g. a reanalysis archive.
 *  - **REAL / EXTERNAL**  - a real source fetched at run time.
 *
 * A downloaded historical reanalysis is never labelled "live", and none of these
 * is a forecast. The badge text comes straight from the backend's
 * `status_label`; the browser does not decide provenance.
 */
import { useCallback, useEffect, useMemo, useState } from "react";

import DatasetQualityPanel from "./DatasetQualityPanel";
import { describeApiError, fetchDatasets } from "../services/dataApi";
import type { DataOrigin, DatasetManifest } from "../types/api";

type State =
  | { status: "loading" }
  | { status: "ready"; datasets: DatasetManifest[]; message: string | null }
  | { status: "error"; message: string };

const ORIGIN_FILTERS: Array<{ value: DataOrigin | "ALL"; label: string }> = [
  { value: "ALL", label: "All" },
  { value: "SYNTHETIC", label: "Synthetic" },
  { value: "HISTORICAL", label: "Historical" },
  { value: "EXTERNAL", label: "Real / external" },
];

export function badgeClass(manifest: DatasetManifest): string {
  if (manifest.origin === "SYNTHETIC") {
    return "badge badge-synthetic";
  }
  return manifest.origin === "EXTERNAL" ? "badge badge-external" : "badge badge-historical";
}

function formatRange(manifest: DatasetManifest): string {
  if (!manifest.time_start || !manifest.time_end) {
    return "time range not recorded";
  }
  return `${manifest.time_start} .. ${manifest.time_end}`;
}

/** The always-visible facts about one dataset. */
function DatasetFacts({ manifest }: { manifest: DatasetManifest }): React.JSX.Element {
  return (
    <>
      <dl className="kv">
        <div>
          <dt>Source</dt>
          <dd>
            {manifest.source}
            <span className="hint">
              {manifest.source_url ? ` (${manifest.source_url})` : " (no URL recorded)"}
            </span>
          </dd>
        </div>
        <div>
          <dt>Period</dt>
          <dd>{formatRange(manifest)}</dd>
        </div>
        <div>
          <dt>Resolution</dt>
          <dd>
            {manifest.resolution_deg === null
              ? "n/a"
              : `${manifest.resolution_deg}° (~${manifest.resolution_km} km)`}
          </dd>
        </div>
        <div>
          <dt>Grid</dt>
          <dd>
            {Object.entries(manifest.dimensions)
              .map(([name, size]) => `${name}=${size}`)
              .join(" · ")}
          </dd>
        </div>
        <div>
          <dt>Variables</dt>
          <dd>{manifest.variables.length > 0 ? manifest.variables.join(", ") : "none"}</dd>
        </div>
        <div>
          <dt>Units</dt>
          <dd>
            {Object.entries(manifest.units)
              .map(([name, unit]) => `${name}: ${unit}`)
              .join(", ") || "n/a"}
          </dd>
        </div>
        <div>
          <dt>Quality</dt>
          <dd>
            {manifest.quality_valid === null || manifest.quality_valid === undefined
              ? "not checked"
              : manifest.quality_valid
                ? "passed"
                : "blocked"}
          </dd>
        </div>
      </dl>
      {manifest.variables_missing.length > 0 ? (
        <p className="hint">
          Not present (reported, not invented): {manifest.variables_missing.join(", ")}.
        </p>
      ) : null}
      {Object.keys(manifest.unit_conversions).length > 0 ? (
        <p className="hint">
          Converted:{" "}
          {Object.entries(manifest.unit_conversions)
            .map(
              ([name, record]) =>
                `${name} ${String(record.original_units ?? "?")} → ${String(
                  record.normalized_units ?? "?",
                )}`,
            )
            .join(" · ")}
        </p>
      ) : null}
      {manifest.coordinate_actions.length > 0 ? (
        <p className="hint">Coordinates: {manifest.coordinate_actions.join(" · ")}</p>
      ) : null}
    </>
  );
}


/** The provenance chain of one dataset, shown when it is expanded. */
function ProvenanceList({ manifest }: { manifest: DatasetManifest }): React.JSX.Element {
  return (
    <div className="dataset-detail">
      <h3>Provenance</h3>
      <ol className="provenance">
        {manifest.processing_steps.map((step) => (
          <li key={`${step.stage}-${step.performed_at ?? ""}`}>
            <strong>{step.stage}</strong> — {step.tool}
            {step.input_hash ? (
              <span className="hint"> in {step.input_hash.slice(0, 12)}</span>
            ) : null}
            {step.output_hash ? (
              <span className="hint"> out {step.output_hash.slice(0, 12)}</span>
            ) : null}
            {step.details ? <span className="hint"> — {step.details}</span> : null}
          </li>
        ))}
      </ol>
      <p className="hint">
        File hash (sha256): {manifest.file_hash || "n/a"} · retrieved {manifest.retrieved_at}
      </p>
      {manifest.license ? <p className="hint">Licence: {manifest.license}</p> : null}
      <DatasetQualityPanel datasetId={manifest.dataset_id} />
    </div>
  );
}

export default function DatasetBrowser(): React.JSX.Element {
  const [state, setState] = useState<State>({ status: "loading" });
  const [origin, setOrigin] = useState<DataOrigin | "ALL">("ALL");
  const [selected, setSelected] = useState<string | null>(null);

  const load = useCallback(async (filter: DataOrigin | "ALL"): Promise<void> => {
    setState({ status: "loading" });
    try {
      const response = await fetchDatasets(filter === "ALL" ? {} : { origin: filter });
      setState({ status: "ready", datasets: response.datasets, message: response.message });
    } catch (error) {
      setState({ status: "error", message: describeApiError(error) });
    }
  }, []);

  useEffect(() => {
    void load(origin);
  }, [load, origin]);

  const counts = useMemo(() => {
    const tally: Record<string, number> = { SYNTHETIC: 0, HISTORICAL: 0, EXTERNAL: 0 };
    for (const manifest of state.status === "ready" ? state.datasets : []) {
      tally[manifest.origin] = (tally[manifest.origin] ?? 0) + 1;
    }
    return tally;
  }, [state]);

  return (
    <section className="panel" aria-labelledby="dataset-browser-heading">
      <header className="panel-header">
        <h2 id="dataset-browser-heading">Ingested datasets</h2>
        <div className="panel-actions">
          <span className="badge badge-synthetic">{counts.SYNTHETIC ?? 0} synthetic</span>
          <span className="badge badge-historical">{counts.HISTORICAL ?? 0} historical</span>
          <span className="badge badge-external">{counts.EXTERNAL ?? 0} real</span>
          <button
            type="button"
            className="button"
            onClick={() => void load(origin)}
            aria-label="Refresh the dataset list"
          >
            Refresh
          </button>
        </div>
      </header>

      <div className="filter-bar" role="group" aria-label="Filter datasets by origin">
        {ORIGIN_FILTERS.map((option) => (
          <button
            key={option.value}
            type="button"
            className={origin === option.value ? "filter-chip is-active" : "filter-chip"}
            onClick={() => setOrigin(option.value)}
            aria-pressed={origin === option.value}
          >
            {option.label}
          </button>
        ))}
      </div>

      {state.status === "loading" ? (
        <p className="status status-loading" role="status">
          Loading datasets ...
        </p>
      ) : null}
      {state.status === "error" ? (
        <p className="status status-error" role="alert">
          {state.message}
        </p>
      ) : null}
      {state.status === "ready" && state.datasets.length === 0 ? (
        <p className="status" role="status">
          {state.message ?? "No datasets match this filter."}
        </p>
      ) : null}

      {state.status === "ready" && state.datasets.length > 0 ? (
        <div className="dataset-list">
          {state.datasets.map((manifest) => (
            <article
              key={manifest.dataset_id}
              className={
                selected === manifest.dataset_id ? "dataset is-selected" : "dataset"
              }
            >
              <div className="dataset-header">
                <button
                  type="button"
                  className="dataset-name"
                  onClick={() =>
                    setSelected(selected === manifest.dataset_id ? null : manifest.dataset_id)
                  }
                  aria-expanded={selected === manifest.dataset_id}
                >
                  {manifest.dataset_id}
                </button>
                <span className={badgeClass(manifest)}>{manifest.status_label}</span>
              </div>

              <DatasetFacts manifest={manifest} />
              {selected === manifest.dataset_id ? (
                <ProvenanceList manifest={manifest} />
              ) : null}
            </article>
          ))}
        </div>
      ) : null}

      <p className="hint">
        Synthetic and historical data are listed and counted separately and are never
        combined in a single figure. A historical reanalysis describes the past; it is not a
        live feed and not a forecast.
      </p>
    </section>
  );
}

